10|// The modifications in 2017 by Glenn Randers-Pehrson include
11|// 1. addition of a PNG_CLEANUP macro,
12|// 2. setting the option to ignore ADLER32 checksums,
13|// 3. adding "#include <string.h>" which is needed on some platforms
14|//    to provide memcpy().
15|// 4. adding read_end_info() and creating an end_info structure.
16|
17|#include <stddef.h>
18|#include <stdint.h>
19|#include <string.h>
20|
21|#include <vector>
22|
23|#define PNG_INTERNAL
24|#include "png.h"
25|
26|struct BufState {
27|  const uint8_t* data;
28|  size_t bytes_left;
29|};
30|
31|struct PngObjectHandler {
32|  png_infop info_ptr = nullptr;
33|  png_structp png_ptr = nullptr;
34|  png_infop end_info_ptr = nullptr;
35|  png_voidp row_ptr = nullptr;
36|  BufState* buf_state = nullptr;
37|
38|  ~PngObjectHandler() {
39|    if (row_ptr)
40|      png_free(png_ptr, row_ptr);
41|    if (end_info_ptr)
42|      png_destroy_read_struct(&png_ptr, &info_ptr, &end_info_ptr);
43|    else if (info_ptr) 
44|      png_destroy_read_struct(&png_ptr, &info_ptr, nullptr);
45|    else
46|      png_destroy_read_struct(&png_ptr, nullptr, nullptr);
47|    delete buf_state;
48|  }
49|};
50|
51|void user_read_data(png_structp png_ptr, png_bytep data, png_size_t length) {
52|  BufState* buf_state = static_cast<BufState*>(png_get_io_ptr(png_ptr));
53|  if (length > buf_state->bytes_left) {
54|    png_error(png_ptr, "read error");
55|  }
56|  memcpy(data, buf_state->data, length);
57|  buf_state->bytes_left -= length;
58|  buf_state->data += length;
59|}
60|
61|static const int kPngHeaderSize = 8;
62|
63|// Entry point for LibFuzzer.
64|// Roughly follows the libpng book example:
65|// http://www.libpng.org/pub/png/book/chapter13.html
66|
67|extern "C" int LLVMFuzzerTestOneInput(const uint8_t* data, size_t size) {
68|  if (size < kPngHeaderSize) {
69|    return 0;
70|  }
71|
72|  std::vector<unsigned char> v(data, data + size);
73|  if (png_sig_cmp(v.data(), 0, kPngHeaderSize)) {
74|    // not a PNG.
75|    return 0;
76|  }
77|
78|  PngObjectHandler png_handler;
79|  png_handler.png_ptr = nullptr;
80|  png_handler.row_ptr = nullptr;
81|  png_handler.info_ptr = nullptr;
82|  png_handler.end_info_ptr = nullptr;
83|
84|  png_handler.png_ptr = png_create_read_struct
85|    (PNG_LIBPNG_VER_STRING, nullptr, nullptr, nullptr);
86|  if (!png_handler.png_ptr) {
87|    return 0;
88|  }
89|
90|#define PNG_CLEANUP \
91|  if(png_handler.png_ptr) \
92|  { \
93|    if (png_handler.row_ptr) \
94|      png_free(png_handler.png_ptr, png_handler.row_ptr); \
95|    if (png_handler.end_info_ptr) \
96|      png_destroy_read_struct(&png_handler.png_ptr, &png_handler.info_ptr,\
97|        &png_handler.end_info_ptr); \
98|    else if (png_handler.info_ptr) \
99|      png_destroy_read_struct(&png_handler.png_ptr, &png_handler.info_ptr,\
100|        nullptr); \
101|    else \
102|      png_destroy_read_struct(&png_handler.png_ptr, nullptr, nullptr); \
103|    png_handler.png_ptr = nullptr; \
104|    png_handler.row_ptr = nullptr; \
105|    png_handler.info_ptr = nullptr; \
106|    png_handler.end_info_ptr = nullptr; \
107|  }
108|
109|  png_handler.info_ptr = png_create_info_struct(png_handler.png_ptr);
110|  if (!png_handler.info_ptr) {
111|    PNG_CLEANUP
112|    return 0;
113|  }
114|
115|  png_handler.end_info_ptr = png_create_info_struct(png_handler.png_ptr);
116|  if (!png_handler.end_info_ptr) {
117|    PNG_CLEANUP
118|    return 0;
119|  }
120|
121|  png_set_crc_action(png_handler.png_ptr, PNG_CRC_QUIET_USE, PNG_CRC_QUIET_USE);
122|
123|#ifdef PNG_IGNORE_ADLER32
124|  png_set_option(png_handler.png_ptr, PNG_IGNORE_ADLER32, PNG_OPTION_ON);
125|#endif
126|
127|  // Setting up reading from buffer.
128|  png_handler.buf_state = new BufState();
129|  png_handler.buf_state->data = data + kPngHeaderSize;
130|  png_handler.buf_state->bytes_left = size - kPngHeaderSize;
131|  png_set_read_fn(png_handler.png_ptr, png_handler.buf_state, user_read_data);
132|  png_set_sig_bytes(png_handler.png_ptr, kPngHeaderSize);
133|
134|  if (setjmp(png_jmpbuf(png_handler.png_ptr))) {
135|    PNG_CLEANUP
136|    return 0;
137|  }
138|
139|  // Reading.
140|  png_read_info(png_handler.png_ptr, png_handler.info_ptr);
141|  png_read_update_info(png_handler.png_ptr, png_handler.info_ptr);
142|  png_handler.row_ptr = png_malloc(
143|      png_handler.png_ptr, png_get_rowbytes(png_handler.png_ptr,
144|                                               png_handler.info_ptr));
145|
146|  // reset error handler to put png_deleter into scope.
147|  if (setjmp(png_jmpbuf(png_handler.png_ptr))) {
148|    PNG_CLEANUP
149|    return 0;
150|  }
151|
152|  png_uint_32 width, height;
153|  int bit_depth, color_type, interlace_type, compression_type;
154|  int filter_type;
155|
156|  if (!png_get_IHDR(png_handler.png_ptr, png_handler.info_ptr, &width,
157|                    &height, &bit_depth, &color_type, &interlace_type,
158|                    &compression_type, &filter_type)) {
159|    PNG_CLEANUP
160|    return 0;
161|  }
162|
163|  // This is going to be too slow.
164|  if (width && height > 100000000 / width) {
165|    PNG_CLEANUP
166|    return 0;
167|  }
168|
169|  int passes = png_set_interlace_handling(png_handler.png_ptr);
170|  png_start_read_image(png_handler.png_ptr);
171|
172|  for (int pass = 0; pass < passes; ++pass) {
173|    for (png_uint_32 y = 0; y < height; ++y) {
174|      png_read_row(png_handler.png_ptr,
175|                   static_cast<png_bytep>(png_handler.row_ptr), nullptr);
176|    }
177|  }
178|
179|  png_read_end(png_handler.png_ptr, png_handler.end_info_ptr);
180|
181|  PNG_CLEANUP
182|
183|  /* TO do: exercise the progressive reader here */
184|
185|  return 0;
186|}

141|int main(int argc, const char **argv)
142|{
143|   /* This program uses the default, <setjmp.h> based, libpng error handling
144|    * mechanism, therefore any local variable that exists before the call to
145|    * setjmp and is changed after the call to setjmp returns successfully must
146|    * be declared with 'volatile' to ensure that their values don't get
147|    * destroyed by longjmp:
148|    */
149|   volatile int result = 1/*fail*/;
150|
151|   if (argc == 4)
152|   {
153|      long x = atol(argv[1]);
154|      long y = atol(argv[2]);
155|      FILE *f = fopen(argv[3], "rb");
156|      volatile png_bytep row = NULL;
157|
158|      if (f != NULL)
159|      {
160|         /* libpng requires a callback function for handling errors; this
161|          * callback must not return.  The default callback function uses a
162|          * stored <setjmp.h> style jmp_buf which is held in a png_struct and
163|          * writes error messages to stderr.  Creating the png_struct is a
164|          * little tricky; just copy the following code.
165|          */
166|         png_structp png_ptr = png_create_read_struct(PNG_LIBPNG_VER_STRING,
167|            NULL, NULL, NULL);
168|
169|         if (png_ptr != NULL)
170|         {
171|            png_infop info_ptr = png_create_info_struct(png_ptr);
172|
173|            if (info_ptr != NULL)
174|            {
175|               /* Declare stack variables to hold pointers to locally allocated
176|                * data.
177|                */
178|
179|               /* Initialize the error control buffer: */
180|               if (setjmp(png_jmpbuf(png_ptr)) == 0)
181|               {
182|                  png_uint_32 width, height;
183|                  int bit_depth, color_type, interlace_method,
184|                     compression_method, filter_method;
185|                  png_bytep row_tmp;
186|
187|                  /* Now associate the recently opened (FILE*) with the default
188|                   * libpng initialization functions.  Sometimes libpng is
189|                   * compiled without stdio support (it can be difficult to do
190|                   * in some environments); in that case you will have to write
191|                   * your own read callback to read data from the (FILE*).
192|                   */
193|                  png_init_io(png_ptr, f);
194|
195|                  /* And read the first part of the PNG file - the header and
196|                   * all the information up to the first pixel.
197|                   */
198|                  png_read_info(png_ptr, info_ptr);
199|
200|                  /* This fills in enough information to tell us the width of
201|                   * each row in bytes, allocate the appropriate amount of
202|                   * space.  In this case png_malloc is used - it will not
203|                   * return if memory isn't available.
204|                   */
205|                  row = png_malloc(png_ptr, png_get_rowbytes(png_ptr,
206|                     info_ptr));
207|
208|                  /* To avoid the overhead of using a volatile auto copy row_tmp
209|                   * to a local here - just use row for the png_free below.
210|                   */
211|                  row_tmp = row;
212|
213|                  /* All the information we need is in the header is returned by
214|                   * png_get_IHDR, if this fails we can now use 'png_error' to
215|                   * signal the error and return control to the setjmp above.
216|                   */
217|                  if (png_get_IHDR(png_ptr, info_ptr, &width, &height,
218|                     &bit_depth, &color_type, &interlace_method,
219|                     &compression_method, &filter_method))
220|                  {
221|                     int passes, pass;
222|
223|                     /* png_set_interlace_handling returns the number of
224|                      * passes required as well as turning on libpng's
225|                      * handling, but since we do it ourselves this is
226|                      * necessary:
227|                      */
228|                     switch (interlace_method)
229|                     {
230|                        case PNG_INTERLACE_NONE:
231|                           passes = 1;
232|                           break;
233|
234|                        case PNG_INTERLACE_ADAM7:
235|                           passes = PNG_INTERLACE_ADAM7_PASSES;
236|                           break;
237|
238|                        default:
239|                           png_error(png_ptr, "pngpixel: unknown interlace");
240|                     }
241|
242|                     /* Now read the pixels, pass-by-pass, row-by-row: */
243|                     png_start_read_image(png_ptr);
244|
245|                     for (pass=0; pass<passes; ++pass)
246|                     {
247|                        png_uint_32 ystart, xstart, ystep, xstep;
248|                        png_uint_32 py;
249|
250|                        if (interlace_method == PNG_INTERLACE_ADAM7)
251|                        {
252|                           /* Sometimes the whole pass is empty because the
253|                            * image is too narrow or too short.  libpng
254|                            * expects to be called for each row that is
255|                            * present in the pass, so it may be necessary to
256|                            * skip the loop below (over py) if the image is
257|                            * too narrow.
258|                            */
259|                           if (PNG_PASS_COLS(width, pass) == 0)
260|                              continue;
261|
262|                           /* We need the starting pixel and the offset
263|                            * between each pixel in this pass; use the macros
264|                            * in png.h:
265|                            */
266|                           xstart = PNG_PASS_START_COL(pass);
267|                           ystart = PNG_PASS_START_ROW(pass);
268|                           xstep = PNG_PASS_COL_OFFSET(pass);
269|                           ystep = PNG_PASS_ROW_OFFSET(pass);
270|                        }
271|
272|                        else
273|                        {
274|                           ystart = xstart = 0;
275|                           ystep = xstep = 1;
276|                        }
277|
278|                        /* To find the pixel, loop over 'py' for each pass
279|                         * reading a row and then checking to see if it
280|                         * contains the pixel.
281|                         */
282|                        for (py = ystart; py < height; py += ystep)
283|                        {
284|                           png_uint_32 px, ppx;
285|
286|                           /* png_read_row takes two pointers.  When libpng
287|                            * handles the interlace the first is filled in
288|                            * pixel-by-pixel, and the second receives the same
289|                            * pixels but they are replicated across the
290|                            * unwritten pixels so far for each pass.  When we
291|                            * do the interlace, however, they just contain
292|                            * the pixels from the interlace pass - giving
293|                            * both is wasteful and pointless, so we pass a
294|                            * NULL pointer.
295|                            */
296|                           png_read_row(png_ptr, row_tmp, NULL);
297|
298|                           /* Now find the pixel if it is in this row; there
299|                            * are, of course, much better ways of doing this
300|                            * than using a for loop:
301|                            */
302|                           if (y == py) for (px = xstart, ppx = 0;
303|                              px < width; px += xstep, ++ppx) if (x == px)
304|                           {
305|                              /* 'ppx' is the index of the pixel in the row
306|                               * buffer.
307|                               */
308|                              print_pixel(png_ptr, info_ptr, row_tmp, ppx);
309|
310|                              /* Now terminate the loops early - we have
311|                               * found and handled the required data.
312|                               */
313|                              goto pass_loop_end;
314|                           } /* x loop */
315|                        } /* y loop */
316|                     } /* pass loop */
317|
318|                     /* Finally free the temporary buffer: */
319|                  pass_loop_end:
320|                     row = NULL;
321|                     png_free(png_ptr, row_tmp);
322|                  }
323|
324|                  else
325|                     png_error(png_ptr, "pngpixel: png_get_IHDR failed");
326|
327|               }
328|
329|               else
330|               {
331|                  /* Else libpng has raised an error.  An error message has
332|                   * already been output, so it is only necessary to clean up
333|                   * locally allocated data:
334|                   */
335|                  if (row != NULL)
336|                  {
337|                     /* The default implementation of png_free never errors out
338|                      * (it just crashes if something goes wrong), but the safe
339|                      * way of using it is still to clear 'row' before calling
340|                      * png_free:
341|                      */
342|                     png_bytep row_tmp = row;
343|                     row = NULL;
344|                     png_free(png_ptr, row_tmp);
345|                  }
346|               }
347|
348|               png_destroy_info_struct(png_ptr, &info_ptr);
349|            }
350|
351|            else
352|               fprintf(stderr, "pngpixel: out of memory allocating png_info\n");
353|
354|            png_destroy_read_struct(&png_ptr, NULL, NULL);
355|         }
356|
357|         else
358|            fprintf(stderr, "pngpixel: out of memory allocating png_struct\n");
359|      }
360|
361|      else
362|         fprintf(stderr, "pngpixel: %s: could not open file\n", argv[3]);
363|   }
364|
365|   else
366|      /* Wrong number of arguments */
367|      fprintf(stderr, "pngpixel: usage: pngpixel x y png-file\n");
368|
369|   return result;
370|}

