35|read_png(FILE *fp)
36|{
37|   png_structp png_ptr = png_create_read_struct(PNG_LIBPNG_VER_STRING,0,0,0);
38|   png_infop info_ptr = NULL;
39|   png_bytep row = NULL, display = NULL;
