98|         }
99|      }
100|   }
101|
102|   /* Make sure to read to the end of the file: */
103|   png_read_end(png_ptr, info_ptr);
104|   png_destroy_read_struct(&png_ptr, &info_ptr, NULL);
105|   free(row);
106|   free(display);
107|   return 1;
